// Convierte la respuesta cruda de values:batchGet en tablas de objetos.
//
// Por qué una sola llamada y no un nodo de Sheets por tab: la API de Google permite
// 60 lecturas por minuto por usuario, y cada nodo de Sheets gasta ~2. Con 5 nodos por
// consulta, dos pacientes conversando a la vez tumbaban la herramienta con un 429.
// Un batchGet de 8 rangos gasta 1.
const ORDEN = ['servicios', 'profesionales', 'citas', 'feriados', 'config', 'pacientes', 'oportunidades', 'actividades'];

const cruda = $input.first().json;
const rangos = cruda.valueRanges || [];

function aObjetos(valores) {
  if (!valores || valores.length < 2) return [];
  const cabeceras = valores[0].map((h) => String(h || '').trim());
  return valores.slice(1)
    .map((fila, i) => {
      const o = { row_number: i + 2 };
      cabeceras.forEach((h, c) => { if (h) o[h] = fila[c] === undefined ? '' : fila[c]; });
      return o;
    })
    .filter((o) => Object.keys(o).length > 1 && Object.entries(o).some(([k, v]) => k !== 'row_number' && String(v).trim()));
}

const tablas = {};
ORDEN.forEach((nombre, i) => { tablas[nombre] = aObjetos((rangos[i] || {}).values); });

return [{
  json: {
    ...tablas,
    conteos: Object.fromEntries(ORDEN.map((n) => [n, tablas[n].length])),
  },
}];

// Resuelve en qué fechas/horas pensaba el paciente, a partir de sus palabras textuales.
// NUNCA falla: si no entiende, asume "lo más próximo disponible" y lo dice en interpretacion.
const TZ = 'America/Costa_Rica';
const entrada = $('Normalizar entrada').first().json;

const ahora = DateTime.now().setZone(TZ);
const hoy = ahora.startOf('day');
const fmt = (d) => d.toFormat('yyyy-MM-dd');
const TILDES = { á: 'a', é: 'e', í: 'i', ó: 'o', ú: 'u', ü: 'u', ñ: 'n' };
const sinTildes = (s) => String(s || '').toLowerCase().replace(/[áéíóúüñ]/g, (c) => TILDES[c]).trim();

let t = ' ' + sinTildes(entrada.fecha_texto).replace(/[.,;!?¿¡]/g, ' ').replace(/\s+/g, ' ') + ' ';

const DIAS = { domingo: 7, lunes: 1, martes: 2, miercoles: 3, jueves: 4, viernes: 5, sabado: 6 };
const MESES = {
  enero: 1, febrero: 2, marzo: 3, abril: 4, mayo: 5, junio: 6, julio: 7,
  agosto: 8, setiembre: 9, septiembre: 9, octubre: 10, noviembre: 11, diciembre: 12,
};

let desde = null;
let hasta = null;
let franja = null;
let horaPretendida = null;
let soloEntreSemana = false;
let diaEspecifico = false;
let etiquetaDia = null;
let entendido = false;

// ---------- 1. Franja horaria ----------
// Ojo: "mañana" es día y franja a la vez. La franja solo cuenta si lleva artículo
// delante ("en la mañana"), así que se saca del texto ANTES de buscar el día.
if (/\b(en|por|de|a) la manana\b/.test(t) || /\bla manana\b/.test(t)) {
  franja = 'manana';
  t = t.replace(/\b((en|por|de|a) )?la manana\b/g, ' ');
  entendido = true;
}
if (/\b(en|por|de|a) la tarde\b/.test(t) || /\bla tarde\b/.test(t)) {
  franja = 'tarde';
  t = t.replace(/\b((en|por|de|a) )?la tarde\b/g, ' ');
  entendido = true;
}
if (/\btemprano\b|\bprimera hora\b/.test(t)) { franja = 'manana'; entendido = true; }
if (/\bal final del dia\b|\bultima hora\b|\btardecita\b|\bnoche\b/.test(t)) { franja = 'tarde'; entendido = true; }

// ---------- 2. Hora pretendida ----------
const mHora = t.match(/\ba? ?las? (\d{1,2})(?::(\d{2}))?\s*(y media|y cuarto)?\s*(am|pm|a m|p m)?/)
  || t.match(/\b(\d{1,2})(?::(\d{2}))?\s*(y media|y cuarto)?\s*(am|pm)\b/);
if (mHora) {
  let h = parseInt(mHora[1], 10);
  let min = mHora[2] ? parseInt(mHora[2], 10) : 0;
  if (mHora[3] === 'y media') min = 30;
  if (mHora[3] === 'y cuarto') min = 15;
  const sufijo = (mHora[4] || '').replace(/\s/g, '');
  if (sufijo === 'pm' && h < 12) h += 12;
  else if (sufijo === 'am' && h === 12) h = 0;
  else if (!sufijo) {
    // Sin am/pm: la clínica abre 08:00–18:00, así que "a las 3" son las 15:00.
    if (h >= 1 && h <= 7) h += 12;
    else if (franja === 'tarde' && h < 12) h += 12;
  }
  if (h >= 0 && h <= 23 && min >= 0 && min <= 59) {
    horaPretendida = String(h).padStart(2, '0') + ':' + String(min).padStart(2, '0');
    entendido = true;
    if (!franja) franja = h < 12 ? 'manana' : 'tarde';
  }
}

// ---------- 3. Día o rango ----------
const proximaOcurrencia = (destino) => {
  const delta = (destino - hoy.weekday + 7) % 7;
  return hoy.plus({ days: delta });
};

if (/\bpasado manana\b/.test(t)) {
  desde = hasta = hoy.plus({ days: 2 }); diaEspecifico = true; entendido = true;
} else if (/\bhoy\b/.test(t)) {
  desde = hasta = hoy; diaEspecifico = true; entendido = true;
} else if (/\bmanana\b/.test(t)) {
  desde = hasta = hoy.plus({ days: 1 }); diaEspecifico = true; entendido = true;
} else if (/\b(la )?(proxima|otra|siguiente) semana\b|\bla semana que viene\b/.test(t)) {
  const lunes = hoy.plus({ days: (8 - hoy.weekday) % 7 || 7 });
  desde = lunes; hasta = lunes.plus({ days: 5 }); etiquetaDia = 'la próxima semana'; entendido = true;
} else if (/\besta semana\b/.test(t)) {
  desde = hoy; hasta = hoy.plus({ days: (6 - hoy.weekday + 7) % 7 }); etiquetaDia = 'esta semana'; entendido = true;
} else if (/\bfin de semana\b/.test(t)) {
  desde = hasta = proximaOcurrencia(6); diaEspecifico = true; etiquetaDia = 'el fin de semana'; entendido = true;
} else if (/\bentre semana\b|\bdias? de semana\b/.test(t)) {
  desde = hoy; hasta = hoy.plus({ days: 21 }); soloEntreSemana = true; etiquetaDia = 'entre semana'; entendido = true;
}

if (!desde) {
  for (const [nombre, num] of Object.entries(DIAS)) {
    if (new RegExp('\\b' + nombre + 's?\\b').test(t)) {
      desde = hasta = proximaOcurrencia(num); diaEspecifico = true; entendido = true; break;
    }
  }
}

// "el 5 de agosto", "el 5", "05/08"
if (!desde) {
  const mFechaLarga = t.match(/\bel? ?(\d{1,2}) de ([a-z]+)/);
  const mFechaCorta = t.match(/\b(\d{1,2})[\/\-](\d{1,2})\b/);
  const mDespues = t.match(/\b(despues|apartir|a partir) del? (\d{1,2})\b/);
  const mAntes = t.match(/\bantes del? (\d{1,2})\b/);
  const mDiaSolo = t.match(/\bel (\d{1,2})\b/);

  const armarDia = (dia, mes) => {
    let cand = hoy.set({ day: 1, month: mes || hoy.month }).set({ day: Math.min(dia, 28) });
    cand = cand.set({ day: dia });
    if (!cand.isValid) return null;
    if (!mes && cand < hoy) cand = cand.plus({ months: 1 });
    return cand;
  };

  if (mFechaLarga && MESES[mFechaLarga[2]]) {
    desde = hasta = armarDia(parseInt(mFechaLarga[1], 10), MESES[mFechaLarga[2]]);
    diaEspecifico = true; entendido = true;
  } else if (mFechaCorta) {
    desde = hasta = armarDia(parseInt(mFechaCorta[1], 10), parseInt(mFechaCorta[2], 10));
    diaEspecifico = true; entendido = true;
  } else if (mDespues) {
    const d = armarDia(parseInt(mDespues[2], 10));
    if (d) { desde = d.plus({ days: 1 }); hasta = desde.plus({ days: 21 }); etiquetaDia = 'después del ' + mDespues[2]; entendido = true; }
  } else if (mAntes) {
    const d = armarDia(parseInt(mAntes[1], 10));
    if (d) { desde = hoy; hasta = d.minus({ days: 1 }); etiquetaDia = 'antes del ' + mAntes[1]; entendido = true; }
  } else if (mDiaSolo) {
    desde = hasta = armarDia(parseInt(mDiaSolo[1], 10));
    diaEspecifico = true; entendido = true;
  }
}

// ---------- 4. Por defecto: lo más próximo ----------
if (!desde || !desde.isValid) { desde = hoy; hasta = hoy.plus({ days: 21 }); diaEspecifico = false; }
if (!hasta || !hasta.isValid || hasta < desde) hasta = desde;
if (desde < hoy) desde = hoy;

// ---------- 5. Texto legible para que el agente lo repita ----------
const nombreDia = (d) => d.setLocale('es').toFormat("cccc d 'de' LLLL");
const nombreFranja = franja === 'manana' ? ' por la mañana' : (franja === 'tarde' ? ' por la tarde' : '');
// "a las 3:00 p. m.", no "a las 15:00": el agente repite este texto tal cual al paciente.
let nombreHora = '';
if (horaPretendida) {
  const [hh, mm] = horaPretendida.split(':').map(Number);
  const h12 = hh % 12 === 0 ? 12 : hh % 12;
  nombreHora = ` a las ${h12}:${String(mm).padStart(2, '0')}${hh < 12 ? ' a. m.' : ' p. m.'}`;
}

let interpretacion;
if (!entendido) {
  interpretacion = 'lo más próximo disponible';
} else if (etiquetaDia) {
  interpretacion = etiquetaDia + nombreFranja + nombreHora;
} else if (diaEspecifico) {
  interpretacion = 'el ' + nombreDia(desde) + nombreFranja + nombreHora;
} else {
  interpretacion = ('lo más próximo disponible' + nombreFranja + nombreHora);
}

return [{
  json: {
    desde: fmt(desde),
    hasta: fmt(hasta),
    hora_pretendida: horaPretendida,
    franja,
    solo_entre_semana: soloEntreSemana,
    dia_especifico: diaEspecifico,
    entendido,
    interpretacion,
    ahora_iso: ahora.toISO(),
    hoy: fmt(hoy),
    texto_original: entrada.fecha_texto || '',
  },
}];

// Calcula los espacios libres reales combinando Servicios, Profesionales, Citas,
// Feriados y el horario de la sede. Implementa las reglas de DM_01 y DM_03.
//
// Las reglas de DÍA por especialidad (endodoncia mar/jue, ortodoncia L/X/V mañana,
// implantes mié tarde o sáb) NO están codificadas acá: salen solas del cruce
// profesionales_habilitados x dias_atencion.
const TZ = 'America/Costa_Rica';
const MINUTOS_ANTES_DEL_CIERRE = 60;   // DM_01: el último espacio, una hora antes del cierre
const TOPE_LARGO_SEMANA = 16 * 60;     // DM_03: nada de +90 min después de las 4:00 p.m.
const TOPE_LARGO_SABADO = 11 * 60;     // DM_03: ni después de las 11:00 los sábados
const DURACION_LARGA = 90;
const HORAS_DE_ANTICIPACION = 2;       // no se ofrece un espacio que arranca ya mismo
const DIAS_HORIZONTE = 21;
const URGENCIAS = { 'PROF-01': [['10:00', '10:30'], ['15:00', '15:30']] };  // DM_01: 2 espacios diarios

const entrada = $('Normalizar entrada').first().json;
const pedido = $('Interpretar la fecha').first().json;

const datos = $('Preparar datos').first().json;
const servicios = datos.servicios;
const profesionales = datos.profesionales;
const citas = datos.citas;
const feriados = new Set(datos.feriados.map((f) => String(f.fecha || '').trim()));
const sede = datos.config[0] || {};

const txt = (v) => (v === undefined || v === null ? '' : String(v)).trim();
const esVerdadero = (v) => txt(v).toUpperCase() === 'TRUE';
const aMin = (hhmm) => {
  const m = txt(hhmm).match(/^(\d{1,2}):(\d{2})/);
  return m ? parseInt(m[1], 10) * 60 + parseInt(m[2], 10) : null;
};
const aHora = (min) => String(Math.floor(min / 60)).padStart(2, '0') + ':' + String(min % 60).padStart(2, '0');
const ABREV = { 1: 'lun', 2: 'mar', 3: 'mie', 4: 'jue', 5: 'vie', 6: 'sab', 7: 'dom' };
const TILDES = { á: 'a', é: 'e', í: 'i', ó: 'o', ú: 'u', ñ: 'n' };
const norm = (s) => txt(s).toLowerCase().replace(/[áéíóúñ]/g, (c) => TILDES[c]);

const salir = (motivo, mensaje) => [{
  json: { ok: false, motivo, mensaje, interpretacion: pedido.interpretacion, alternativas: [], slots: [] },
}];

// ---------- 1. El servicio ----------
// Al reagendar, el servicio sale de la CITA localizada, no del modelo: se mueve la
// misma cita y no se inventa otra.
const idServicioEfectivo = txt($('Localizar cita').first().json.id_servicio) || txt(entrada.id_servicio);
const servicio = servicios.find((s) => txt(s.id_servicio) === idServicioEfectivo);
if (!servicio) {
  return salir('servicio_no_disponible',
    'No encuentro ese servicio en el catálogo de la clínica.');
}
if (!esVerdadero(servicio.activo)) {
  return salir('servicio_no_disponible',
    `${servicio.nombre} no se está ofreciendo en este momento.`);
}
const duracion = parseInt(txt(servicio.duracion_min), 10) || 30;

// ---------- 2. Profesionales elegibles ----------
const habilitados = txt(servicio.profesionales_habilitados).split(';').map(txt).filter(Boolean);
const equipo = profesionales.filter((p) => habilitados.includes(txt(p.id_profesional)) && esVerdadero(p.activo));
if (!equipo.length) {
  return salir('servicio_no_disponible',
    `Ahora mismo no hay un profesional disponible para ${servicio.nombre}.`);
}

// ---------- 3. Horarios ----------
// Profesionales.horario admite "08:00-18:00" y "Mié:13:00-18:00;Sáb:08:00-13:00"
function ventanaProfesional(horario, diaSemana) {
  const h = txt(horario);
  if (h.includes(':') && /[a-zA-ZáéíóúÁÉÍÓÚ]/.test(h.split('-')[0] || '')) {
    for (const bloque of h.split(';')) {
      const [dia, rango] = bloque.split(/:(.+)/);
      if (norm(dia).slice(0, 3) === ABREV[diaSemana] && rango) {
        const [ini, fin] = rango.split('-');
        return [aMin(ini), aMin(fin)];
      }
    }
    return null;
  }
  const [ini, fin] = h.split('-');
  const a = aMin(ini); const b = aMin(fin);
  return a !== null && b !== null ? [a, b] : null;
}

// Config.horario_atencion: "Lun-Vie 08:00-18:00, Sáb 08:00-13:00"
function ventanaSede(diaSemana) {
  const partes = txt(sede.horario_atencion).split(',');
  for (const parte of partes) {
    const m = norm(parte).match(/([a-z]{3})\s*(?:-\s*([a-z]{3}))?\s*(\d{1,2}:\d{2})\s*-\s*(\d{1,2}:\d{2})/);
    if (!m) continue;
    const idx = (a) => Object.entries(ABREV).find(([, v]) => v === a)?.[0];
    const d1 = parseInt(idx(m[1]), 10);
    const d2 = m[2] ? parseInt(idx(m[2]), 10) : d1;
    if (d1 && diaSemana >= d1 && diaSemana <= d2) return [aMin(m[3]), aMin(m[4])];
  }
  return null;
}

// ---------- 4. Citas ocupadas, por profesional y día ----------
const ocupadas = {};
for (const c of citas) {
  if (!['Solicitada', 'Confirmada'].includes(txt(c.estado))) continue;
  const clave = txt(c.id_profesional) + '|' + txt(c.fecha);
  const ini = aMin(c.hora_inicio); const fin = aMin(c.hora_fin);
  if (ini === null || fin === null) continue;
  (ocupadas[clave] = ocupadas[clave] || []).push([ini, fin]);
}

// ---------- 5. Barrido de días ----------
const ahora = DateTime.fromISO(pedido.ahora_iso, { zone: TZ });
const minimo = ahora.plus({ hours: HORAS_DE_ANTICIPACION });
const hoy = DateTime.fromISO(pedido.hoy, { zone: TZ });
const pedidoDesde = DateTime.fromISO(pedido.desde, { zone: TZ });
// Se barre siempre desde hoy, aunque el paciente haya pedido un día lejano: es lo que
// permite ofrecer alternativas más cercanas sin una segunda llamada.
const inicioBarrido = hoy;
const finBarrido = pedidoDesde.plus({ days: DIAS_HORIZONTE });

// `dur` y `team` se pasan por parámetro para poder calcular también la malla de la
// valoración inicial con este MISMO generador. Duplicarlo en otro nodo sería dos fuentes
// para el mismo cálculo, que es justo lo que este motor existe para evitar.
function slotsDelDia(dia, paso, dur = duracion, team = equipo) {
  const fecha = dia.toFormat('yyyy-MM-dd');
  const ds = dia.weekday;
  const salida = [];
  if (ds === 7 || feriados.has(fecha)) return salida;            // domingos y feriados: cerrado
  if (pedido.solo_entre_semana && ds === 6) return salida;
  const sedeV = ventanaSede(ds);
  if (!sedeV) return salida;
  const limiteSede = sedeV[1] - MINUTOS_ANTES_DEL_CIERRE;
  const topeLargo = ds === 6 ? TOPE_LARGO_SABADO : TOPE_LARGO_SEMANA;

  for (const p of team) {
    const dias = txt(p.dias_atencion).split(';').map((d) => norm(d).slice(0, 3));
    if (!dias.includes(ABREV[ds])) continue;
    const propia = ventanaProfesional(p.horario, ds);
    if (!propia) continue;
    const abre = Math.max(propia[0], sedeV[0]);
    const cierra = Math.min(propia[1], sedeV[1]);
    const limite = Math.min(cierra, limiteSede);
    const choques = (ocupadas[txt(p.id_profesional) + '|' + fecha] || [])
      .concat(URGENCIAS[txt(p.id_profesional)] ? URGENCIAS[txt(p.id_profesional)].map(([a, b]) => [aMin(a), aMin(b)]) : []);

    for (let ini = abre; ini + dur <= limite; ini += paso) {
      if (dur > DURACION_LARGA && ini > topeLargo) continue;
      const fin = ini + dur;
      if (choques.some(([a, b]) => ini < b && fin > a)) continue;
      const arranque = dia.set({ hour: Math.floor(ini / 60), minute: ini % 60 });
      if (arranque < minimo) continue;
      salida.push({
        fecha,
        dia_semana: ds,
        hora_inicio: aHora(ini),
        hora_fin: aHora(fin),
        minuto_inicio: ini,
        id_profesional: txt(p.id_profesional),
        profesional: txt(p.nombre),
      });
    }
  }
  return salida;
}

// Malla anclada a la duración del servicio: una limpieza de 45 min da 08:00, 08:45,
// 09:30... y una valoración de 30 da 08:00, 08:30... La agenda se ve distinta según
// el servicio, que es como funciona una clínica de verdad.
let slots = [];
for (let d = inicioBarrido; d <= finBarrido; d = d.plus({ days: 1 })) {
  slots = slots.concat(slotsDelDia(d, duracion));
}

// Pasada de rescate: si el día que pidió quedó vacío, se recalcula ESE día con malla
// de 15 min. La malla anclada puede no ver un hueco que dejó una cancelación, y el
// contrato es no decir "no hay" cuando sí hay.
let huboRescate = false;
if (pedido.dia_especifico) {
  const dia = DateTime.fromISO(pedido.desde, { zone: TZ });
  if (!slots.some((s) => s.fecha === pedido.desde)) {
    const rescate = slotsDelDia(dia, 15);
    if (rescate.length) { slots = slots.concat(rescate); huboRescate = true; }
  }
}

slots.sort((a, b) => (a.fecha === b.fecha ? a.minuto_inicio - b.minuto_inicio : a.fecha < b.fecha ? -1 : 1));

// Lo que el paciente pidió, contra todo lo que existe. Cuando pidió un día concreto,
// "en rango" es ese día; cuando pidió un rango ("la próxima semana", "después del 15"),
// es ese rango. `slots` completo queda igual para poder ofrecer alternativas.
const enRango = slots.filter((s) => s.fecha >= pedido.desde && s.fecha <= pedido.hasta);

// ¿Por qué no hay nada el día que pidió? El motivo tiene que ser el REAL: decir que el
// profesional no atiende sábados cuando el problema es que ese sábado es feriado es
// mentirle al paciente.
let motivoDia = null;
if (pedido.dia_especifico && !slots.some((s) => s.fecha === pedido.desde)) {
  const dia = DateTime.fromISO(pedido.desde, { zone: TZ });
  const atiendeEseDia = equipo.some((p) => txt(p.dias_atencion).split(';')
    .map((d) => norm(d).slice(0, 3)).includes(ABREV[dia.weekday]));
  if (feriados.has(pedido.desde)) motivoDia = 'feriado';
  else if (dia.weekday === 7) motivoDia = 'domingo';
  else if (!atiendeEseDia) motivoDia = 'dia_no_habilitado';
  else motivoDia = 'dia_lleno';
}

// ---------- 6. La salida de emergencia del paciente nuevo ----------
// Si el servicio pedido NO es la valoración, se calcula TAMBIÉN su malla. Cuesta solo CPU
// sobre datos que ya se leyeron —ni una llamada más a Sheets— y le permite a "Validar
// reglas" ofrecer horarios concretos en la misma respuesta en vez de devolver
// `alternativas: []` y confiar en que el modelo haga una segunda llamada. Un contrato que
// depende de que el modelo haga algo es un contrato roto.
const SRV_VALORACION = 'SRV-001';
let slotsValoracion = [];
if (txt(servicio.id_servicio) !== SRV_VALORACION) {
  const sv = servicios.find((s) => txt(s.id_servicio) === SRV_VALORACION);
  if (sv && esVerdadero(sv.activo)) {
    const durV = parseInt(txt(sv.duracion_min), 10) || 30;
    const habV = txt(sv.profesionales_habilitados).split(';').map(txt).filter(Boolean);
    const equipoV = profesionales.filter((p) => habV.includes(txt(p.id_profesional)) && esVerdadero(p.activo));
    if (equipoV.length) {
      for (let d = inicioBarrido; d <= finBarrido; d = d.plus({ days: 1 })) {
        slotsValoracion = slotsValoracion.concat(slotsDelDia(d, durV, durV, equipoV));
      }
      slotsValoracion.sort((a, b) => (a.fecha === b.fecha
        ? a.minuto_inicio - b.minuto_inicio : a.fecha < b.fecha ? -1 : 1));
      slotsValoracion = slotsValoracion.slice(0, 60);
    }
  }
}

return [{
  json: {
    ok: true,
    motivo: motivoDia,
    slots_valoracion: slotsValoracion,
    interpretacion: pedido.interpretacion,
    id_servicio: txt(servicio.id_servicio),
    servicio: txt(servicio.nombre),
    duracion_min: duracion,
    requiere_valoracion: esVerdadero(servicio.requiere_valoracion),
    equipo: equipo.map((p) => ({ id: txt(p.id_profesional), nombre: txt(p.nombre), dias: txt(p.dias_atencion) })),
    hubo_rescate: huboRescate,
    total_slots: slots.length,
    total_en_rango: enRango.length,
    slots,
    slots_en_rango: enRango,
  },
}];

// Ordena los espacios libres por cercanía a lo que el paciente pidió y arma el mensaje.
// El contrato es que NUNCA se devuelva vacío ni un "no hay" pelado: un resultado vacío
// es exactamente lo que hace alucinar al modelo.
const TZ = 'America/Costa_Rica';
const MAX_ALTERNATIVAS = 6;
const VALORACIONES = ['SRV-001', 'SRV-016'];

const motor = $input.first().json;
const pedido = $('Interpretar la fecha').first().json;
const loc = $('Localizar cita').first().json;

const aMin = (hhmm) => {
  const m = String(hhmm || '').match(/^(\d{1,2}):(\d{2})/);
  return m ? parseInt(m[1], 10) * 60 + parseInt(m[2], 10) : null;
};

// "martes 11 de agosto, 9:00 a. m."
function enEspanol(slot) {
  const d = DateTime.fromISO(slot.fecha, { zone: TZ }).setLocale('es');
  const min = aMin(slot.hora_inicio);
  const h24 = Math.floor(min / 60);
  const h12 = h24 % 12 === 0 ? 12 : h24 % 12;
  const mm = min % 60;
  const hora = h12 + (mm ? ':' + String(mm).padStart(2, '0') : ':00') + (h24 < 12 ? ' a. m.' : ' p. m.');
  return `${d.toFormat("cccc d 'de' LLLL")}, ${hora}, con ${slot.profesional}`;
}

const publico = (s) => ({
  texto: enEspanol(s),
  fecha: s.fecha,
  hora_inicio: s.hora_inicio,
  hora_fin: s.hora_fin,
  id_profesional: s.id_profesional,
  profesional: s.profesional,
});

// distancia = |Δ días| x 100
//           + |Δ minutos respecto a la hora pretendida| / 15
//           - 40 si cae en la franja que pidió
//           - 25 si es el mismo día que pidió
function distancia(slot) {
  const dias = Math.abs(DateTime.fromISO(slot.fecha, { zone: TZ })
    .diff(DateTime.fromISO(pedido.desde, { zone: TZ }), 'days').days);
  let d = dias * 100;
  if (pedido.hora_pretendida) d += Math.abs(slot.minuto_inicio - aMin(pedido.hora_pretendida)) / 15;
  else d += slot.minuto_inicio / 600;                     // a igualdad, lo más temprano
  const esManana = slot.minuto_inicio < 12 * 60;
  if (pedido.franja === 'manana' && esManana) d -= 40;
  if (pedido.franja === 'tarde' && !esManana) d -= 40;
  if (slot.fecha === pedido.desde) d -= 25;
  return d;
}

// Se ordena y se deja UN profesional por fecha+hora. Si no, una valoración —que la hacen
// los cuatro— ofrecería "8:00 con Dulce María" y "8:00 con Andrés" como si fueran dos
// espacios distintos. Al paciente le importa la hora, no con quién.
function ordenar(lista) {
  const vistos = new Set();
  return [...lista].sort((a, b) => distancia(a) - distancia(b)).filter((s) => {
    const clave = s.fecha + '|' + s.hora_inicio;
    if (vistos.has(clave)) return false;
    vistos.add(clave);
    return true;
  });
}

const enRango = motor.slots_en_rango || [];
const todos = motor.slots || [];

// ¿Está libre exactamente lo que pidió?
let exactos = enRango;
if (pedido.hora_pretendida) exactos = enRango.filter((s) => s.hora_inicio === pedido.hora_pretendida);
if (pedido.franja === 'manana') exactos = exactos.filter((s) => s.minuto_inicio < 12 * 60);
if (pedido.franja === 'tarde') exactos = exactos.filter((s) => s.minuto_inicio >= 12 * 60);

const disponible = exactos.length > 0;
const base = disponible ? exactos : (enRango.length ? enRango : todos);
const alternativas = ordenar(base).slice(0, MAX_ALTERNATIVAS).map(publico);

// ---------- mensaje redactado para que el agente lo parafrasee ----------
const nombreDia = (f) => DateTime.fromISO(f, { zone: TZ }).setLocale('es').toFormat("cccc d 'de' LLLL");
let mensaje;

if (!alternativas.length) {
  mensaje = `No tengo espacios de ${motor.servicio} en las próximas semanas. `
    + 'Coordinemos con la clínica para buscarle un espacio.';
} else if (motor.motivo === 'feriado') {
  mensaje = `Ese día es feriado y la clínica está cerrada. `
    + `Lo más cercano que tengo es ${alternativas[0].texto}.`;
} else if (motor.motivo === 'domingo') {
  mensaje = `Los domingos la clínica no abre. Lo más cercano que tengo es ${alternativas[0].texto}.`;
} else if (motor.motivo === 'dia_no_habilitado') {
  const dias = motor.equipo.map((p) => `${p.nombre} atiende ${p.dias.split(';').join(', ')}`).join('; ');
  mensaje = `${motor.servicio} no se agenda ese día: ${dias}. `
    + `Lo más cercano que tengo es ${alternativas[0].texto}.`;
} else if (motor.motivo === 'dia_lleno') {
  mensaje = `Ese día ya está lleno. Lo más cercano que tengo es `
    + `${alternativas.slice(0, 3).map((a) => a.texto).join('; ')}.`;
} else if (disponible) {
  mensaje = `Sí tengo espacio: ${alternativas.slice(0, 3).map((a) => a.texto).join('; ')}.`;
} else if (pedido.hora_pretendida) {
  const mismoDia = alternativas.filter((a) => a.fecha === pedido.desde);
  mensaje = mismoDia.length
    ? `Esa hora está ocupada, pero ${nombreDia(pedido.desde)} me quedan `
      + `${mismoDia.slice(0, 3).map((a) => a.hora_inicio).join(' y ')}.`
    : `Esa hora está ocupada y ese día no me queda nada más. Lo más cercano es ${alternativas[0].texto}.`;
} else {
  mensaje = `Para ${motor.servicio} lo más cercano que tengo es `
    + `${alternativas.slice(0, 3).map((a) => a.texto).join('; ')}.`;
}

// ---------- aviso: la regla de valoración, dicha por quien la conoce ----------
// Consultar NO bloquea —informa—, pero tiene que decir la verdad sobre la regla. Si calla,
// el modelo la deduce de la columna `requiere_valoracion` del SERVICIO y afirma cosas
// sobre el PACIENTE: el 2026-08-28 (exec 27517) contestó "la limpieza no requiere
// valoración previa" a alguien que preguntaba por la regla de la clínica, y le habría
// contestado igual a un paciente nuevo, al que "agendar" después rebota.
//
// Solo se emite cuando cambia lo que el paciente puede hacer. Para el resto de los casos
// viajan los hechos crudos (`paciente_existente`, `valoracion`) y la regla vive en el
// prompt: la política es estable, el estado del paciente no.
const val = loc.valoracion || { estado: 'ninguna', texto: '' };
const proximas = loc.citas_proximas || [];
const esValoracion = VALORACIONES.includes(motor.id_servicio);
const yaValorado = val.estado === 'realizada';
const reglaA = loc.paciente_existente !== true;      // primera visita a la clínica
const reglaB = motor.requiere_valoracion === true;   // el servicio la exige

let avisoRegla = '';
if (esValoracion) {
  avisoRegla = '';
} else if (!yaValorado && reglaA) {
  avisoRegla = val.estado === 'agendada'
    ? `Es su primera visita, así que la clínica pide una valoración inicial antes de ${motor.servicio}. `
      + `Ya tiene la suya agendada para ${val.texto}, y el tratamiento va después de esa.`
    : `Es su primera visita, así que la clínica pide una valoración inicial antes de ${motor.servicio} `
      + '(30 minutos, 15.000 colones, con examen completo, plan por escrito y radiografías).';
} else if (!yaValorado && reglaB) {
  avisoRegla = val.estado === 'agendada'
    ? `${motor.servicio} requiere una valoración previa y usted ya tiene la suya agendada para `
      + `${val.texto}. El tratamiento se agenda después de esa.`
    : `${motor.servicio} requiere una valoración previa (30 minutos, 15.000 colones) antes de reservarlo.`;
} else if (yaValorado && reglaB) {
  avisoRegla = `${motor.servicio} requiere valoración previa, y usted ya la tiene hecha `
    + `(${val.texto}), así que se lo puedo agendar directamente.`;
}

// `nota_valoracion` va SIEMPRE, incluso cuando ninguna regla está activa. Es el hecho ya
// redactado, listo para cuando el paciente pregunte "¿puedo agendar sin valoración?".
// `aviso` es lo que hay que decir sin que lo pidan; esto es lo que hay que decir cuando
// lo piden. Sin este campo el modelo contestaba esa pregunta desde la columna
// `requiere_valoracion` del catálogo y se equivocaba de sujeto: hablaba del servicio
// cuando le preguntaban por la persona (2026-08-28, execs 27517 y 27565).
let notaValoracion;
if (esValoracion) {
  notaValoracion = 'Esta es justamente la cita de valoración inicial.';
} else if (reglaA) {
  notaValoracion = 'La clínica pide una valoración inicial en la primera visita, y esta es '
    + `la suya, así que ${motor.servicio} va después de esa.`;
} else if (reglaB && !yaValorado) {
  notaValoracion = `${motor.servicio} requiere una valoración previa y usted todavía no la tiene`
    + `${val.estado === 'agendada' ? `, aunque ya la tiene agendada para ${val.texto}` : ' hecha'}.`;
} else if (reglaB && yaValorado) {
  notaValoracion = `${motor.servicio} requiere una valoración previa y usted ya la tiene hecha `
    + `(${val.texto}), así que no le hace falta otra.`;
} else {
  notaValoracion = 'La clínica pide la valoración inicial solo en la primera visita. Usted ya '
    + `está registrado con nosotros, así que para ${motor.servicio} no le hace falta.`;
}

// Cada vez que el paciente va a agendar se le recuerdan las citas que ya tiene.
const recordatorio = proximas.length
  ? `Ya tiene ${proximas.length === 1 ? 'una cita agendada' : `${proximas.length} citas agendadas`}: `
    + `${proximas.map((c) => `${c.servicio}, ${c.texto}`).join('; ')}.`
  : '';

return [{
  json: {
    ok: true,
    accion: 'consultar_disponibilidad',
    interpretacion: motor.interpretacion,
    servicio: motor.servicio,
    id_servicio: motor.id_servicio,
    duracion_min: motor.duracion_min,
    disponible,
    motivo: motor.motivo,
    alternativas,
    mensaje,
    // contexto del paciente: los hechos, para que el modelo no los deduzca
    paciente_existente: loc.paciente_existente === true,
    valoracion: val,
    citas_proximas: proximas,
    aviso: [avisoRegla, recordatorio].filter(Boolean).join(' '),
    nota_valoracion: notaValoracion,
  },
}];

// Regla de DM_03 que depende SOLO del paciente y del servicio, no de la hora:
// toda persona que nunca ha sido atendida pasa primero por una valoración inicial.
//
// Corre ANTES de resolver a qué espacio se refería el paciente, a propósito. Si corriera
// después, pedir una limpieza a una hora que no existe en la malla devolvería "ese espacio
// no está disponible" y el paciente nuevo se iría con alternativas que no puede reservar.
//
// La otra regla de DM_03 —no dos citas de tratamiento el mismo día— sí depende del espacio
// elegido y se valida en "Confirmar y preparar", contra la relectura fresca de Citas.
//
// Son DOS reglas distintas y hasta el 2026-08-28 se confundían en una sola condición:
//   A. PACIENTE: la primera visita pasa por valoración, sea cual sea el servicio.
//   B. SERVICIO: algunos tratamientos la exigen aunque el paciente ya sea conocido.
// La B no miraba si la valoración había ocurrido, así que rebotaba para siempre: 21 de los
// 35 servicios activos eran inagendables de por vida. Ahora ambas se levantan con una
// valoración YA ATENDIDA, que es lo que `Localizar cita` calcula en `valoracion.estado`.
const SRV_VALORACION = 'SRV-001';
const SRV_VALORACION_NINO = 'SRV-016';

const motor = $input.first().json;
const entrada = $('Normalizar entrada').first().json;
const datos = $('Preparar datos').first().json;
const loc = $('Localizar cita').first().json;

const txt = (v) => (v === undefined || v === null ? '' : String(v)).trim();
// La hoja mezcla "+506 8888-9999" y "(+506) 8888-9999": se compara solo por dígitos.
const soloDigitos = (t) => txt(t).replace(/\D/g, '').replace(/^506/, '');
const telPaciente = soloDigitos(entrada.telefono);

const paciente = datos.pacientes.find((p) => soloDigitos(p.telefono) && soloDigitos(p.telefono) === telPaciente);
const oportunidad = datos.oportunidades.find((o) => soloDigitos(o.telefono) === telPaciente
  && !['Ganada', 'Perdida'].includes(txt(o.etapa)));

const valoracion = loc.valoracion || { estado: 'ninguna', texto: '' };
const proximas = loc.citas_proximas || [];

// Cada vez que se intenta agendar, se le recuerdan al paciente las citas que ya tiene.
// Va en el `mensaje`, redactado para él, no como un dato suelto que el modelo deba
// interpretar por su cuenta.
const recordatorio = proximas.length
  ? ` Por cierto, ya tiene ${proximas.length === 1 ? 'una cita agendada' : `${proximas.length} citas agendadas`}: `
    + `${proximas.map((c) => `${c.servicio}, ${c.texto}`).join('; ')}.`
  : '';

const esValoracion = [SRV_VALORACION, SRV_VALORACION_NINO].includes(motor.id_servicio);
const yaValorado = valoracion.estado === 'realizada';
const reglaA = !paciente;                            // primera visita a la clínica
const reglaB = motor.requiere_valoracion === true;   // el servicio la exige

if (!esValoracion && !yaValorado && (reglaA || reglaB)) {
  const razon = reglaA
    ? 'Como es su primera vez en la clínica, primero necesita una cita de valoración inicial'
    : `${motor.servicio} requiere una valoración previa`;

  // Ya tiene la valoración reservada: no hay nada nuevo que ofrecerle, solo esperar a que
  // ocurra. Ofrecerle más horarios de valoración acá sería empujarlo a duplicarla.
  if (valoracion.estado === 'agendada') {
    return [{
      json: {
        ok: false, accion: 'agendar', motivo: 'requiere_valoracion_previa', disponible: false,
        interpretacion: motor.interpretacion, servicio: motor.servicio,
        id_servicio_sugerido: null,
        valoracion, citas_proximas: proximas, paciente_existente: !!paciente,
        nota_valoracion: `${motor.servicio} requiere una valoración previa y la suya ya está `
          + `agendada para ${valoracion.texto}.`,
        mensaje: `${razon}, y usted ya tiene la suya agendada para ${valoracion.texto}. `
          + `${motor.servicio} se agenda después de esa cita.${recordatorio}`,
        alternativas: [],
      },
    }];
  }

  // Horarios REALES de la valoración, calculados por "Calcular slots libres" sobre los
  // mismos datos ya leídos. Antes esto devolvía `alternativas: []` y un mensaje escrito
  // para el modelo ("consulte la disponibilidad..."), confiando en que hiciera una segunda
  // llamada. No siempre la hacía, y el paciente se quedaba sin una sola hora concreta.
  // Un contrato que depende de que el modelo haga algo es un contrato roto.
  const TZ = 'America/Costa_Rica';
  const enEspanol = (s) => {
    const d = DateTime.fromISO(s.fecha, { zone: TZ }).setLocale('es');
    const [hh, mm] = String(s.hora_inicio).split(':').map(Number);
    const h12 = hh % 12 === 0 ? 12 : hh % 12;
    return `${d.toFormat("cccc d 'de' LLLL")}, ${h12}:${String(mm).padStart(2, '0')}`
      + `${hh < 12 ? ' a. m.' : ' p. m.'}, con ${s.profesional}`;
  };
  const vistos = new Set();
  const alternativas = (motor.slots_valoracion || [])
    .filter((s) => {
      const clave = s.fecha + '|' + s.hora_inicio;
      if (vistos.has(clave)) return false;
      vistos.add(clave);
      return true;
    })
    .slice(0, 6)
    .map((s) => ({
      texto: enEspanol(s), fecha: s.fecha, hora_inicio: s.hora_inicio, hora_fin: s.hora_fin,
      id_profesional: s.id_profesional, profesional: s.profesional,
    }));

  return [{
    json: {
      ok: false, accion: 'agendar', motivo: 'requiere_valoracion_previa', disponible: false,
      interpretacion: motor.interpretacion, servicio: motor.servicio,
      // por si el agente prefiere volver a consultar disponibilidad con ESTE servicio
      id_servicio_sugerido: SRV_VALORACION,
      valoracion, citas_proximas: proximas, paciente_existente: !!paciente,
      nota_valoracion: reglaA
        ? 'La clínica pide una valoración inicial en la primera visita, y esta es la suya, '
          + `así que ${motor.servicio} va después de esa.`
        : `${motor.servicio} requiere una valoración previa y usted todavía no la tiene hecha.`,
      mensaje: `${razon}. Dura 30 minutos, cuesta 15.000 colones e incluye el examen completo, `
        + 'el plan de tratamiento por escrito y las radiografías necesarias.'
        + (alternativas.length
          ? ` Le puedo ofrecer: ${alternativas.slice(0, 3).map((a) => a.texto).join('; ')}.`
          : '')
        + recordatorio,
      alternativas,
    },
  }];
}

return [{
  json: {
    ...motor,
    ok: true,
    paciente_existente: !!paciente,
    id_paciente: paciente ? txt(paciente.id_paciente) : null,
    nombre_paciente: paciente ? txt(paciente.nombre_completo) : txt(entrada.nombre_paciente),
    telefono: txt(entrada.telefono),
    id_oportunidad: oportunidad ? txt(oportunidad.id_oportunidad) : null,
    paciente_row: paciente || null,
    // viajan hasta "Respuesta agendada" para poder recordarle sus otras citas
    valoracion,
    citas_proximas: proximas,
  },
}];

// A cuál de los espacios libres se refería el paciente cuando dijo "dale, el de las 3".
// Se resuelve contra la disponibilidad RECALCULADA en este momento, no contra lo que se
// ofreció turnos atrás: así se detecta si el espacio se ocupó mientras conversaban.
const TZ = 'America/Costa_Rica';

const motor = $input.first().json;
const pedido = $('Interpretar la fecha').first().json;
const entrada = $('Normalizar entrada').first().json;

const TILDES = { á: 'a', é: 'e', í: 'i', ó: 'o', ú: 'u', ñ: 'n' };
const norm = (s) => String(s || '').toLowerCase().replace(/[áéíóúñ]/g, (c) => TILDES[c]);
const texto = norm(entrada.fecha_texto);

const aMin = (h) => {
  const m = String(h || '').match(/^(\d{1,2}):(\d{2})/);
  return m ? parseInt(m[1], 10) * 60 + parseInt(m[2], 10) : null;
};
function enEspanol(s) {
  const d = DateTime.fromISO(s.fecha, { zone: TZ }).setLocale('es');
  const min = aMin(s.hora_inicio);
  const h24 = Math.floor(min / 60);
  const h12 = h24 % 12 === 0 ? 12 : h24 % 12;
  const hora = h12 + ':' + String(min % 60).padStart(2, '0') + (h24 < 12 ? ' a. m.' : ' p. m.');
  return `${d.toFormat("cccc d 'de' LLLL")}, ${hora}, con ${s.profesional}`;
}
const publico = (s) => ({
  texto: enEspanol(s), fecha: s.fecha, hora_inicio: s.hora_inicio, hora_fin: s.hora_fin,
  id_profesional: s.id_profesional, profesional: s.profesional,
});

const todos = motor.slots || [];
const fallar = (motivo, mensaje, opciones) => [{
  json: {
    ok: false, accion: 'agendar', motivo, mensaje,
    interpretacion: motor.interpretacion, servicio: motor.servicio, id_servicio: motor.id_servicio,
    disponible: false,
    alternativas: (opciones && opciones.length ? opciones : todos.slice(0, 6)).map(publico),
  },
}];

if (!todos.length) {
  return fallar('fuera_de_horario',
    `No tengo espacios de ${motor.servicio} en las próximas semanas.`, []);
}

// ---------- filtrar por lo que dijo ----------
let candidatos = todos;
if (pedido.dia_especifico) candidatos = candidatos.filter((s) => s.fecha === pedido.desde);
if (pedido.hora_pretendida) candidatos = candidatos.filter((s) => s.hora_inicio === pedido.hora_pretendida);
if (pedido.franja === 'manana') candidatos = candidatos.filter((s) => s.minuto_inicio < 12 * 60);
if (pedido.franja === 'tarde') candidatos = candidatos.filter((s) => s.minuto_inicio >= 12 * 60);

// Un profesional por fecha+hora. Sin esto, una valoración —que la hacen los cuatro—
// se ofrecería como "08:00, 08:00, 08:30, 08:30".
const vistos = new Set();
candidatos = candidatos.filter((s) => {
  const clave = s.fecha + '|' + s.hora_inicio;
  if (vistos.has(clave)) return false;
  vistos.add(clave);
  return true;
});

// "el primero", "el segundo", "la tercera": posición sobre lo que se ofreció.
const ORDINALES = { primer: 1, primero: 1, primera: 1, segundo: 2, segunda: 2, tercer: 3, tercero: 3, tercera: 3, cuarto: 4, cuarta: 4 };
const mOrdinal = Object.keys(ORDINALES).find((k) => new RegExp('\\b' + k + '\\b').test(texto));
if (mOrdinal && candidatos.length > 1) {
  const i = ORDINALES[mOrdinal] - 1;
  if (candidatos[i]) candidatos = [candidatos[i]];
}

if (!candidatos.length) {
  const cercanos = pedido.dia_especifico ? todos.filter((s) => s.fecha === pedido.desde) : [];
  return fallar('no_coincide',
    `Ese espacio ya no está disponible. Le puedo ofrecer ${enEspanol(todos[0])}.`,
    cercanos.length ? cercanos : todos.slice(0, 6));
}

// Varios candidatos a la misma hora y día pero con distinto profesional no es ambigüedad
// para el paciente: se toma el primero. Ambiguo de verdad es "el jueves" con tres horas.
const distintos = new Set(candidatos.map((s) => s.fecha + ' ' + s.hora_inicio));
if (distintos.size > 1) {
  // Repartidas a lo largo del día, NO las 4 primeras. Con 18 espacios libres las 4 primeras
  // son todas de la mañana, así que el espacio de la tarde que el paciente venía pidiendo
  // desaparecía de la lista y el modelo lo leía como "ya no está disponible" (2026-08-07).
  const n = Math.min(5, candidatos.length);
  const paso = (candidatos.length - 1) / (n - 1);
  const muestra = candidatos.length <= n
    ? candidatos
    : Array.from({ length: n }, (_, i) => candidatos[Math.round(i * paso)]);
  return fallar('ambiguo',
    `Ese día tengo ${candidatos.length} espacios libres, por ejemplo: `
    + `${muestra.map((s) => s.hora_inicio).join(', ')}. ¿A qué hora le sirve?`,
    muestra);
}

const elegido = candidatos[0];
const { slots, ...resto } = motor;   // slots es grande y ya no hace falta aguas abajo
return [{
  json: {
    ...resto,                        // arrastra los datos del paciente que puso "Validar reglas"
    ok: true, accion: 'agendar',
    slot: elegido, slot_texto: enEspanol(elegido),
    alternativas: [publico(elegido)],
    // por si "Confirmar y preparar" tiene que ofrecer otro día
    alternativas_todas: todos.slice(0, 40).map(publico),
  },
}];

const v = ($input.first().json.valueRanges || [])[0] || {};
const filas = v.values || [];
const cab = (filas[0] || []).map((h) => String(h || '').trim());
const citas = filas.slice(1).map((f) => Object.fromEntries(cab.map((h, i) => [h, f[i] === undefined ? '' : f[i]])));
return [{ json: { citas } }];

// Última verificación antes de escribir: el espacio tiene que seguir libre.
// Google Sheets no da atomicidad, así que este re-chequeo es la única defensa contra
// una reserva duplicada. Suficiente para un demo; no para producción real.
const TZ = 'America/Costa_Rica';

const datos = $('Resolver slot pedido').first().json;
const entrada = $('Normalizar entrada').first().json;
const citas = $input.first().json.citas;   // viene de "Preparar citas frescas"

const txt = (v) => (v === undefined || v === null ? '' : String(v)).trim();
const aMin = (h) => {
  const m = String(h || '').match(/^(\d{1,2}):(\d{2})/);
  return m ? parseInt(m[1], 10) * 60 + parseInt(m[2], 10) : null;
};

const slot = datos.slot;
const ini = aMin(slot.hora_inicio);
const fin = aMin(slot.hora_fin);

const chocando = citas.find((c) => txt(c.id_profesional) === slot.id_profesional
  && txt(c.fecha) === slot.fecha
  && ['Solicitada', 'Confirmada'].includes(txt(c.estado))
  && ini < aMin(c.hora_fin) && fin > aMin(c.hora_inicio));

if (chocando) {
  return [{
    json: {
      ok: false, sigue_libre: false, accion: 'agendar', motivo: 'no_coincide', disponible: false,
      interpretacion: datos.interpretacion, servicio: datos.servicio,
      mensaje: 'Ese espacio se acaba de ocupar. Consulte la disponibilidad de nuevo para '
        + 'ofrecerle los horarios que quedan.',
      alternativas: [],
    },
  }];
}

// DM_03: un paciente no puede tener dos citas de tratamiento el mismo día. Se valida acá
// y no en "Validar reglas" porque depende del espacio elegido, y contra la relectura
// fresca de Citas para que cuente una cita que se acabe de crear.
const reglas = $('Validar reglas').first().json;
const mismoDia = reglas.id_paciente && citas.find((c) => txt(c.id_paciente) === txt(reglas.id_paciente)
  && txt(c.fecha) === slot.fecha
  && ['Solicitada', 'Confirmada'].includes(txt(c.estado)));
if (mismoDia) {
  const otroDia = (datos.alternativas_todas || []).filter((s) => s.fecha !== slot.fecha);
  return [{
    json: {
      ok: false, sigue_libre: false, accion: 'agendar', motivo: 'dos_citas_mismo_dia', disponible: false,
      interpretacion: datos.interpretacion, servicio: datos.servicio,
      mensaje: `Ya tiene una cita ese día a las ${txt(mismoDia.hora_inicio)}. `
        + 'La clínica no agenda dos tratamientos el mismo día. '
        + (otroDia.length ? `Le puedo ofrecer ${otroDia[0].texto}.` : ''),
      alternativas: otroDia.slice(0, 6),
    },
  }];
}

// ---------- ids nuevos ----------
const siguiente = (lista, prefijo, ancho) => {
  const nums = lista.map((v) => parseInt(txt(v).replace(prefijo, ''), 10)).filter((n) => !isNaN(n));
  return prefijo + String((nums.length ? Math.max(...nums) : 0) + 1).padStart(ancho, '0');
};
const tablas = $('Preparar datos').first().json;
const actividades = tablas.actividades;
const pacientes = tablas.pacientes;

// El calendario del profesional que atiende. Va acá porque el nodo de Calendar está al
// final de la cadena y ahí $json ya es la respuesta del append de Actividades.
const profesional = (tablas.profesionales || []).find((p) => txt(p.id_profesional) === slot.id_profesional);
const idCalendar = profesional ? txt(profesional.id_calendar) : '';

const idCita = siguiente(citas.map((c) => c.id_cita), 'CITA-', 4);
const idPaciente = datos.id_paciente || siguiente(pacientes.map((p) => p.id_paciente), 'PAC-', 4);
const idActividad = siguiente(actividades.map((a) => a.id_actividad), 'ACT-', 5);
const ahora = DateTime.now().setZone(TZ);

// El correo del paciente para el aviso de la cita. Gana el que acaba de dar por WhatsApp
// sobre el que ya estaba en la hoja: si lo dictó de nuevo es porque el viejo no servía.
// Puede quedar vacío y no pasa nada: el correo es un aviso, nunca un requisito para
// agendar. `Fila paciente` lo escribe en Pacientes!D para las próximas veces.
const emailPaciente = txt(entrada.email) || txt((datos.paciente_row || {}).email);

// Datos de la sede para el correo. Salen de Config, que ya se leyó en "Preparar datos":
// el workflow de correos no vuelve a tocar Sheets.
const sede = (tablas.config || [])[0] || {};

return [{
  json: {
    ...datos,
    ok: true,
    sigue_libre: true,
    id_cita: idCita,
    id_paciente: idPaciente,
    id_actividad: idActividad,
    id_calendar: idCalendar,
    // Costa Rica es UTC-6 todo el año (no hay horario de verano), así que el offset se
    // pone explícito en vez de confiar en cómo interprete n8n una fecha sin zona.
    inicio_iso: `${slot.fecha}T${slot.hora_inicio}:00-06:00`,
    fin_iso: `${slot.fecha}T${slot.hora_fin}:00-06:00`,
    fecha_creacion: ahora.toFormat('yyyy-MM-dd HH:mm'),
    nombre_paciente: datos.nombre_paciente || txt(entrada.nombre_paciente) || 'Paciente WhatsApp',
    email_paciente: emailPaciente,
    sede: {
      nombre: txt(sede.nombre),
      direccion: txt(sede.direccion),
      link_maps: txt(sede.link_maps),
      telefono: txt(sede.telefono),
      whatsapp: txt(sede.whatsapp),
    },
  },
}];

// La cita nace SOLICITADA: la clínica la confirma por WhatsApp 24 h antes (DM_03).
//
// Va como arreglo de celdas en el orden de las columnas A:R, no como objeto, porque se
// escribe con values:append y valueInputOption=RAW. Con el nodo normal de Sheets, Google
// interpreta "08:30" como una hora y lo devuelve como "8:30", que no cuadra con el resto
// de la hoja.
const d = $('Confirmar y preparar').first().json;
return [{
  json: {
    valores: [[
      d.id_cita,
      d.id_paciente,
      d.slot.id_profesional,
      d.id_servicio,
      '',                              // id_tratamiento
      d.id_oportunidad || '',
      'SEDE-01',
      d.slot.fecha,
      d.slot.hora_inicio,
      d.slot.hora_fin,
      'Solicitada',
      'Bot WhatsApp',
      'FALSE',                         // recordatorio_enviado
      'FALSE',                         // confirmada_por_paciente
      'Bot',
      d.fecha_creacion,
      `Agendada por el bot: ${d.servicio}`,
      '',                              // id_evento_calendar
    ]],
  },
}];

// Se reescriben solo los campos seguros; para un paciente que ya existe son los
// mismos valores que ya tenía, así que es un no-op.
const d = $('Confirmar y preparar').first().json;
const p = d.paciente_row || {};
return [{
  json: {
    id_paciente: d.id_paciente,
    nombre_completo: d.nombre_paciente,
    telefono: d.telefono,
    // Pacientes!D. `email_paciente` ya viene resuelto (el que dictó ahora, o el que ya
    // estaba en la hoja), así que para un paciente que no dio correo esto reescribe el
    // mismo valor y nunca lo borra.
    email: d.email_paciente || p.email || '',
    sede_preferida: p.sede_preferida || 'SEDE-01',
    estado: p.estado || 'Nuevo',
    fecha_registro: p.fecha_registro || d.fecha_creacion.slice(0, 10),
    canal_origen: p.canal_origen || 'WhatsApp',
    consentimiento_datos: p.consentimiento_datos || 'TRUE',
  },
}];

const d = $('Confirmar y preparar').first().json;
return [{
  json: {
    id_actividad: d.id_actividad,
    fecha_hora: d.fecha_creacion,
    id_paciente: d.id_paciente,
    id_oportunidad: d.id_oportunidad || '',
    id_cita: d.id_cita,
    canal: 'WhatsApp',
    tipo: 'Confirmación',
    direccion: 'Entrante',
    resumen: `Cita solicitada por el bot: ${d.servicio}, ${d.slot.fecha} ${d.slot.hora_inicio}`,
    intencion: 'Agendar',
    sentimiento: 'Positivo',
    generado_por: 'Bot',
    requiere_seguimiento: 'FALSE',
    url_documento: '',
  },
}];

const d = $('Confirmar y preparar').first().json;
return [{
  json: {
    id_oportunidad: d.id_oportunidad,
    id_paciente: d.id_paciente,
    etapa: 'Cita agendada',
    fecha_ultima_interaccion: d.fecha_creacion,
  },
}];

const d = $('Confirmar y preparar').first().json;
const loc = $('Localizar cita').first().json;

// Las citas que YA tenía ANTES de esta (el contexto se calculó al entrar, antes de
// escribir). Se le recuerdan al confirmar para que no se le junten dos sin darse cuenta.
const previas = loc.citas_proximas || [];
const recordatorio = previas.length
  ? ` Además de esta, ya tenía ${previas.length === 1 ? 'una cita' : `${previas.length} citas`}: `
    + `${previas.map((c) => `${c.servicio}, ${c.texto}`).join('; ')}.`
  : '';

return [{
  json: {
    ok: true,
    accion: 'agendar',
    agendada: true,
    disponible: true,
    motivo: null,
    interpretacion: d.interpretacion,
    servicio: d.servicio,
    id_cita: d.id_cita,
    cita: {
      texto: d.slot_texto,
      fecha: d.slot.fecha,
      hora_inicio: d.slot.hora_inicio,
      hora_fin: d.slot.hora_fin,
      id_profesional: d.slot.id_profesional,
      profesional: d.slot.profesional,
    },
    alternativas: [],
    mensaje: `Cita solicitada para ${d.slot_texto}. Queda registrada como SOLICITADA: `
      + `la clínica la confirma por WhatsApp 24 horas antes.${recordatorio}`,
    paciente_existente: loc.paciente_existente === true,
    valoracion: loc.valoracion || { estado: 'ninguna', texto: '' },
    citas_proximas: previas,
    aviso: recordatorio.trim(),
    // Payload para "Enviar correo de la cita". Si el paciente no dio correo, `email` va
    // vacío y el sub-workflow corta solo: la cita ya quedó escrita igual.
    correo: {
      tipo: 'nueva',
      email: d.email_paciente || '',
      nombre_paciente: d.nombre_paciente,
      servicio: d.servicio,
      texto_cita: d.slot_texto,
      profesional: d.slot.profesional,
      id_cita: d.id_cita,
      nota: '',
      texto_anterior: '',
      sede_nombre: (d.sede || {}).nombre || '',
      sede_direccion: (d.sede || {}).direccion || '',
      sede_link_maps: (d.sede || {}).link_maps || '',
      sede_telefono: (d.sede || {}).telefono || '',
      sede_whatsapp: (d.sede || {}).whatsapp || '',
    },
  },
}];

// Único punto de salida del sub-workflow. Garantiza la forma del contrato: nunca vacío,
// siempre con mensaje y con alternativas.
const j = $input.first().json;

// Un profesional por fecha+hora, acá y no en cada rama: al paciente le importa la hora,
// no con quién. Sin esto una valoración —que la hacen los cuatro— se ofrecería como
// "9:00 con Dulce María" y "9:00 con Carolina" como si fueran dos espacios distintos.
const vistos = new Set();
const alternativas = (Array.isArray(j.alternativas) ? j.alternativas : []).filter((a) => {
  const clave = `${a.fecha}|${a.hora_inicio}`;
  if (vistos.has(clave)) return false;
  vistos.add(clave);
  return true;
});
return [{
  json: {
    ok: j.ok !== false,
    interpretacion: j.interpretacion || 'lo más próximo disponible',
    servicio: j.servicio || '',
    disponible: j.disponible === true,
    agendada: j.agendada === true,
    motivo: j.motivo || null,
    // cuando la regla de valoración previa bloquea, el agente tiene que volver a
    // consultar disponibilidad con ESTE servicio. Va en null cuando el paciente YA tiene
    // la valoración agendada: ahí no hay nada que consultar, solo que llegue el día.
    id_servicio_sugerido: j.id_servicio_sugerido || null,
    id_cita: j.id_cita || null,
    cita: j.cita || null,
    alternativas,
    mensaje: j.mensaje || 'No pude resolver la consulta de agenda.',
    // Contexto del paciente. Este nodo es un whitelist: lo que no se nombre acá, no sale.
    // `paciente_existente` y `valoracion` son HECHOS que el modelo no puede deducir de
    // `catalogo_servicios` —esa hoja habla del servicio, no de la persona— y `aviso` es
    // la explicación ya redactada de por qué se puede o no agendar.
    paciente_existente: j.paciente_existente === true,
    valoracion: j.valoracion || { estado: 'ninguna', texto: '' },
    citas_proximas: Array.isArray(j.citas_proximas) ? j.citas_proximas : [],
    aviso: j.aviso || '',
    // `aviso` es lo que hay que decir sin que lo pidan; `nota_valoracion` es lo que hay
    // que decir cuando el paciente pregunta por la regla. Va siempre poblado.
    nota_valoracion: j.nota_valoracion || '',
  },
}];

// De qué cita habla el paciente. Es la puerta de entrada de confirmar, cancelar y reagendar,
// y además decide con qué servicio calcula espacios el motor cuando se reagenda.
//
// Dos vías de entrada, a propósito:
//   · con `token`  → viene de un enlace del correo e identifica una cita concreta.
//   · sin `token`  → viene del agente por WhatsApp y se resuelve por teléfono.
//
// Ninguna de las dos le pide `id_cita` al modelo: cada dato que el modelo no tiene que
// llenar es un dato que no puede inventar. Mismo criterio que con `id_oportunidad`.
//
// Para consultar y agendar NO localiza una cita, pero sí arma el CONTEXTO del paciente:
// si ya es conocido, en qué estado está su valoración inicial y qué citas tiene por
// delante. Ese contexto es lo que faltaba. Sin él (2026-08-28, exec 27517) el modelo
// deducía si hacía falta valoración leyendo la columna `requiere_valoracion` del
// servicio —que habla del SERVICIO, no de la persona— y le prometía a un paciente cosas
// que "agendar" después rechazaba. Los datos ya están en memoria: no cuesta ni una
// lectura más de Sheets.
const GESTION = ['confirmar', 'cancelar', 'reagendar'];
const ACTIVAS = ['Solicitada', 'Confirmada', 'Reprogramada'];
const VALORACIONES = ['SRV-001', 'SRV-016'];
const TZ = 'America/Costa_Rica';

// Va DESPUÉS de "Interpretar la fecha" para poder desambiguar "la del jueves" reusando el
// resolver, así que los datos del CRM se piden por nombre y no por $input.
const datos = $('Preparar datos').first().json;
const entrada = $('Normalizar entrada').first().json;
const pedido = $('Interpretar la fecha').first().json;
const accion = String(entrada.accion || '').trim();

const txt = (v) => (v === undefined || v === null ? '' : String(v)).trim();
// La hoja mezcla "+506 8888-9999" y "(+506) 8888-9999": se compara solo por dígitos.
const digitos = (t) => txt(t).replace(/\D/g, '').replace(/^506/, '');

const hoy = DateTime.now().setZone(TZ).toFormat('yyyy-MM-dd');

const enEspanol = (c) => {
  const d = DateTime.fromISO(txt(c.fecha), { zone: TZ }).setLocale('es');
  const [hh, mm] = txt(c.hora_inicio).split(':').map(Number);
  const h12 = hh % 12 === 0 ? 12 : hh % 12;
  return `${d.toFormat("cccc d 'de' LLLL")}, ${h12}:${String(mm).padStart(2, '0')}`
    + `${hh < 12 ? ' a. m.' : ' p. m.'}`;
};
const publico = (c) => ({
  texto: enEspanol(c), fecha: txt(c.fecha), hora_inicio: txt(c.hora_inicio),
  hora_fin: txt(c.hora_fin), id_profesional: txt(c.id_profesional), id_cita: txt(c.id_cita),
});
const porFechaHora = (a, b) => (txt(a.fecha) + txt(a.hora_inicio))
  .localeCompare(txt(b.fecha) + txt(b.hora_inicio));

const nombreServicio = (id) => {
  const s = datos.servicios.find((x) => txt(x.id_servicio) === txt(id));
  return s ? txt(s.nombre) : txt(id);
};
// Las citas que se le recuerdan al paciente llevan el nombre del servicio: "su limpieza
// del sábado" le sirve; "su CITA-0031" no le dice nada a nadie.
const citaPublica = (c) => ({
  texto: enEspanol(c), fecha: txt(c.fecha), hora_inicio: txt(c.hora_inicio),
  id_cita: txt(c.id_cita), estado: txt(c.estado), servicio: nombreServicio(c.id_servicio),
});

const buscarPaciente = (tel) => (tel
  ? datos.pacientes.find((p) => digitos(p.telefono) && digitos(p.telefono) === tel) || null
  : null);

// Contexto del paciente, idéntico para todas las acciones. Es lo que le permite al motor
// explicar POR QUÉ deja o no deja agendar, en vez de dejar que el modelo lo adivine.
function contexto(pac) {
  if (!pac) {
    return {
      paciente_existente: false,
      valoracion: { estado: 'ninguna', texto: '' },
      citas_proximas: [],
    };
  }
  const mias = datos.citas.filter((c) => txt(c.id_paciente) === txt(pac.id_paciente));
  const proximas = mias
    .filter((c) => ACTIVAS.includes(txt(c.estado)) && txt(c.fecha) >= hoy)
    .sort(porFechaHora);

  // Solo una valoración YA ATENDIDA levanta la regla del servicio. Una agendada a futuro
  // todavía no, y la diferencia importa porque el mensaje cambia: "usted ya fue valorado"
  // no es lo mismo que "su valoración es el jueves, el tratamiento va después de esa".
  const vals = mias.filter((c) => VALORACIONES.includes(txt(c.id_servicio)));
  const realizada = vals.find((c) => txt(c.estado) === 'Completada'
    || (ACTIVAS.includes(txt(c.estado)) && txt(c.fecha) < hoy));
  const agendada = vals
    .filter((c) => ACTIVAS.includes(txt(c.estado)) && txt(c.fecha) >= hoy)
    .sort(porFechaHora)[0];

  return {
    paciente_existente: true,
    valoracion: {
      estado: realizada ? 'realizada' : (agendada ? 'agendada' : 'ninguna'),
      texto: realizada ? enEspanol(realizada) : (agendada ? enEspanol(agendada) : ''),
    },
    citas_proximas: proximas.map(citaPublica),
  };
}

// Consultar y agendar no localizan una cita: siguen de largo con el servicio que pidió el
// modelo, pero llevándose el contexto del paciente.
if (!GESTION.includes(accion)) {
  const pac = buscarPaciente(digitos(entrada.telefono));
  return [{
    json: {
      ok: true,
      accion,
      id_servicio: txt(entrada.id_servicio),
      cita: null,
      paciente: pac ? { ...pac, fila: pac.row_number } : null,
      ...contexto(pac),
    },
  }];
}

const fallar = (motivo, mensaje, opciones = []) => [{
  json: { ok: false, accion, motivo, mensaje, disponible: false, alternativas: opciones, cita: null },
}];

const token = txt(entrada.token);
let cita = null;
let paciente = null;

if (token) {
  cita = datos.citas.find((c) => txt(c.token_gestion) === token) || null;
  if (!cita) {
    return fallar('token_invalido',
      'Este enlace ya no es válido. Escríbanos por WhatsApp y le ayudamos con su cita.');
  }
  if (!ACTIVAS.includes(txt(cita.estado))) {
    return fallar('cita_no_activa',
      `Esa cita figura como ${txt(cita.estado).toLowerCase()}, así que no hay nada pendiente por hacer.`);
  }
  paciente = datos.pacientes.find((p) => txt(p.id_paciente) === txt(cita.id_paciente)) || null;
} else {
  paciente = buscarPaciente(digitos(entrada.telefono));
  if (!paciente) {
    return fallar('sin_citas',
      'No encuentro ninguna cita a su nombre. ¿Quiere que le busque un espacio?');
  }

  let suyas = datos.citas
    .filter((c) => txt(c.id_paciente) === txt(paciente.id_paciente)
      && ACTIVAS.includes(txt(c.estado)) && txt(c.fecha) >= hoy)
    .sort(porFechaHora);

  if (!suyas.length) {
    return fallar('sin_citas',
      'No tiene citas próximas agendadas. ¿Quiere que le busque un espacio?');
  }

  // Si el paciente dijo de cuál habla ("la del jueves"), se filtra por lo que entendió el
  // resolver de fechas. Reusa esa pieza en vez de repetir un mini-parser acá.
  if (suyas.length > 1 && pedido.dia_especifico) {
    const delDia = suyas.filter((c) => txt(c.fecha) === pedido.desde);
    if (delDia.length) suyas = delDia;
  }

  // Se devuelven TODAS, no las primeras N. Una lista cortada hace que el modelo afirme que
  // algo no existe: es el bug del 2026-08-07 con otro disfraz.
  if (suyas.length > 1) {
    const cuál = suyas.length === 2 ? '¿Cuál de las dos?' : '¿Cuál de ellas?';
    return fallar('ambiguo',
      `Tiene ${suyas.length} citas próximas: ${suyas.map(enEspanol).join('; ')}. ${cuál}`,
      suyas.map(publico));
  }
  cita = suyas[0];
}

const servicio = datos.servicios.find((s) => txt(s.id_servicio) === txt(cita.id_servicio));
const profesional = datos.profesionales.find((p) => txt(p.id_profesional) === txt(cita.id_profesional));

return [{
  json: {
    ok: true,
    accion,
    // Al reagendar, el servicio sale de la CITA, no de lo que diga el modelo: se mueve la
    // misma cita, no se inventa otra. "Calcular slots libres" lee este campo.
    id_servicio: txt(cita.id_servicio),
    cita: {
      ...cita,
      fila: cita.row_number,
      texto: enEspanol(cita),
      servicio: servicio ? txt(servicio.nombre) : txt(cita.id_servicio),
      duracion_min: servicio ? (parseInt(txt(servicio.duracion_min), 10) || 30) : 30,
      profesional: profesional ? txt(profesional.nombre) : txt(cita.id_profesional),
      id_calendar: profesional ? txt(profesional.id_calendar) : '',
    },
    paciente: paciente ? { ...paciente, fila: paciente.row_number } : null,
    ...contexto(paciente),
  },
}];

// Un solo nodo para confirmar, cancelar y reagendar. Están juntos a propósito: la cola que
// sigue (escribir en Citas, mover el evento de Calendar, registrar la actividad, responder)
// es la misma para las tres, y con tres nodos distintos esa cola no podría referenciar al
// que corrió. Acá cada acción arma la misma forma:
//
//   { actualizaciones[], borrar_evento, crear_evento, actividad, respuesta }
const TZ = 'America/Costa_Rica';
const CARGO = 10000;

const loc = $('Localizar cita').first().json;
const entrada = $('Normalizar entrada').first().json;
const c = loc.cita;
const f = c.fila;
const ahora = DateTime.now().setZone(TZ);
const sello = ahora.toFormat('yyyy-MM-dd HH:mm');
const notaPrevia = String(c.notas || '').trim();

// Datos para el correo de aviso. La sede sale de Config, que ya se leyó en "Preparar
// datos": el sub-workflow de correos no vuelve a tocar Sheets. El correo del paciente
// sale de su ficha; si está vacío, el sub-workflow corta solo y la gestión igual se hizo.
const sede = ($('Preparar datos').first().json.config || [])[0] || {};
const correoBase = {
  email: String((loc.paciente || {}).email || '').trim(),
  nombre_paciente: String((loc.paciente || {}).nombre_completo || '').trim(),
  servicio: c.servicio,
  id_cita: c.id_cita,
  nota: '',
  texto_anterior: '',
  sede_nombre: String(sede.nombre || '').trim(),
  sede_direccion: String(sede.direccion || '').trim(),
  sede_link_maps: String(sede.link_maps || '').trim(),
  sede_telefono: String(sede.telefono || '').trim(),
  sede_whatsapp: String(sede.whatsapp || '').trim(),
};

const base = {
  id_cita: c.id_cita,
  fila: f,
  borrar_evento: null,
  crear_evento: null,
  cargo_por_cancelacion_tardia: false,
  // `tipo` vacío = no se manda correo. Es el caso de confirmar: por decisión del
  // proyecto la confirmación vive ÚNICAMENTE en WhatsApp y no genera correo.
  correo: { ...correoBase, tipo: '', texto_cita: c.texto, profesional: c.profesional },
};
const citaPublica = (t, s) => ({
  texto: t, fecha: s.fecha, hora_inicio: s.hora_inicio, hora_fin: s.hora_fin,
  id_profesional: s.id_profesional, profesional: s.profesional,
});

// ---------------------------------------------------------------- confirmar
if (loc.accion === 'confirmar') {
  return [{ json: { ...base, accion: 'confirmar',
    // K = estado, N = confirmada_por_paciente
    actualizaciones: [
      { range: `Citas!K${f}`, values: [['Confirmada']] },
      { range: `Citas!N${f}`, values: [['TRUE']] },
    ],
    actividad: {
      tipo: 'Confirmación',
      resumen: `El paciente confirmó su cita de ${c.servicio} del ${c.fecha} a las ${c.hora_inicio}`,
      intencion: 'Agendar',
    },
    respuesta: {
      ok: true, motivo: null, disponible: true, agendada: false,
      servicio: c.servicio, id_cita: c.id_cita,
      cita: citaPublica(c.texto, c),
      mensaje: `Listo, su cita de ${c.servicio} quedó confirmada para ${c.texto} con ${c.profesional}. `
        + 'Le esperamos. Si necesita moverla, avísenos con al menos 24 horas de anticipación.',
    },
  } }];
}

// ---------------------------------------------------------------- cancelar
// DM_04, textual: "Las citas se pueden cancelar o reprogramar sin costo hasta veinticuatro
// horas antes de la hora agendada. Las cancelaciones con menos de veinticuatro horas de
// aviso generan un cargo de 10.000 colones, que se cobra en la siguiente cita."
//
// La cita se cancela IGUAL aunque falten menos de 24 h: negarse sería peor que el cargo,
// porque el paciente no va a ir de todos modos y la clínica pierde el espacio sin saberlo.
// Acá solo se informa. No se cobra nada ni se lleva la cuenta de las tres ausencias.
if (loc.accion === 'cancelar') {
  const horas = DateTime.fromISO(`${c.fecha}T${c.hora_inicio}`, { zone: TZ })
    .diff(ahora, 'hours').hours;
  const tardia = horas < 24;
  const nota = `${notaPrevia} | Cancelada por el paciente el ${sello}`
    + (tardia ? ` (menos de 24 h: cargo de ${CARGO.toLocaleString('es-CR')} colones)` : ' (sin cargo)');

  return [{ json: { ...base, accion: 'cancelar',
    cargo_por_cancelacion_tardia: tardia,
    correo: {
      ...correoBase,
      tipo: 'cancelada',
      texto_cita: c.texto,
      profesional: c.profesional,
      nota: tardia
        ? `Como faltaban menos de 24 horas para la cita, aplica el cargo de `
          + `${CARGO.toLocaleString('es-CR')} colones que la clínica cobra en su siguiente visita.`
        : '',
    },
    actualizaciones: [
      { range: `Citas!K${f}`, values: [['Cancelada']] },
      { range: `Citas!Q${f}`, values: [[nota.trim()]] },
    ],
    borrar_evento: c.id_evento_calendar && c.id_calendar
      ? { id: c.id_evento_calendar, calendar: c.id_calendar } : null,
    actividad: {
      tipo: 'Seguimiento',
      resumen: `Cita ${c.id_cita} cancelada por el paciente${tardia ? ' con menos de 24 h de aviso' : ''}`,
      intencion: 'Reprogramar',
    },
    respuesta: {
      ok: true, motivo: tardia ? 'cancelada_con_cargo' : null, disponible: false, agendada: false,
      servicio: c.servicio, id_cita: c.id_cita,
      cita: citaPublica(c.texto, c),
      mensaje: `Cancelé su cita de ${c.servicio} del ${c.texto}.`
        + (tardia
          ? ` Como faltaban menos de 24 horas, aplica el cargo de ${CARGO.toLocaleString('es-CR')} `
            + 'colones que la clínica cobra en la siguiente cita.'
          : ' No tiene ningún cargo.')
        + ' Cuando quiera volver a agendar, con gusto le busco un espacio.',
    },
  } }];
}

// ---------------------------------------------------------------- reagendar
// Se MUEVE la misma fila en vez de cancelar y crear otra: así el id_cita y el token del
// correo siguen sirviendo, y el histórico queda en `notas` y en Actividades. `Reprogramada`
// ya existe en los enums de Config!R, no hubo que inventar un estado.
//
// El evento de Calendar se borra y se recrea en vez de moverse: si cambió el profesional
// cambió el calendario, y mover un evento entre calendarios no es un PATCH.
const resuelto = $input.first().json;    // viene de "Resolver slot pedido"
const s = resuelto.slot;
const prof = $('Preparar datos').first().json.profesionales
  .find((p) => String(p.id_profesional || '').trim() === s.id_profesional);
const calNuevo = prof ? String(prof.id_calendar || '').trim() : '';

return [{ json: { ...base, accion: 'reagendar',
  correo: {
    ...correoBase,
    tipo: 'reprogramada',
    texto_cita: resuelto.slot_texto,
    profesional: s.profesional,
    texto_anterior: c.texto,
  },
  actualizaciones: [
    { range: `Citas!C${f}`, values: [[s.id_profesional]] },
    // H fecha, I hora_inicio, J hora_fin, K estado: contiguas, una sola escritura
    { range: `Citas!H${f}:K${f}`, values: [[s.fecha, s.hora_inicio, s.hora_fin, 'Reprogramada']] },
    // vuelve a requerir confirmación y a entrar en el recordatorio del día anterior
    { range: `Citas!M${f}:N${f}`, values: [['FALSE', 'FALSE']] },
    { range: `Citas!Q${f}`, values: [[`${notaPrevia} | Reprogramada desde ${c.fecha} ${c.hora_inicio} el ${sello}`.trim()]] },
  ],
  borrar_evento: c.id_evento_calendar && c.id_calendar
    ? { id: c.id_evento_calendar, calendar: c.id_calendar } : null,
  crear_evento: calNuevo ? {
    calendar: calNuevo,
    // Costa Rica es UTC-6 todo el año, sin horario de verano: el offset va explícito
    inicio_iso: `${s.fecha}T${s.hora_inicio}:00-06:00`,
    fin_iso: `${s.fecha}T${s.hora_fin}:00-06:00`,
    summary: `${c.servicio} — ${loc.paciente ? loc.paciente.nombre_completo : ''}`.trim(),
    description: `id_cita: ${c.id_cita}\nid_paciente: ${c.id_paciente}\n`
      + `Reprogramada desde ${c.fecha} ${c.hora_inicio}`,
  } : null,
  actividad: {
    tipo: 'Seguimiento',
    resumen: `Cita ${c.id_cita} reprogramada de ${c.fecha} ${c.hora_inicio} a ${s.fecha} ${s.hora_inicio}`,
    intencion: 'Reprogramar',
  },
  respuesta: {
    ok: true, motivo: null, disponible: true, agendada: true,
    servicio: c.servicio, id_cita: c.id_cita,
    cita: citaPublica(resuelto.slot_texto, s),
    mensaje: `Listo, moví su cita de ${c.servicio}: queda para ${resuelto.slot_texto}. `
      + 'Queda como reprogramada y la clínica se la confirma 24 horas antes.',
  },
} }];

// Una fila en Actividades por cada gestión, con los enums que ya viven en Config.
const prep = $('Preparar gestión').first().json;
const loc = $('Localizar cita').first().json;
const datos = $('Preparar datos').first().json;

const ids = datos.actividades
  .map((a) => parseInt(String(a.id_actividad || '').replace(/\D/g, ''), 10))
  .filter((n) => !Number.isNaN(n));

return [{
  json: {
    id_actividad: 'ACT-' + String((ids.length ? Math.max(...ids) : 0) + 1).padStart(5, '0'),
    fecha_hora: DateTime.now().setZone('America/Costa_Rica').toFormat('yyyy-MM-dd HH:mm'),
    id_paciente: loc.cita.id_paciente,
    id_oportunidad: loc.cita.id_oportunidad || '',
    id_cita: loc.cita.id_cita,
    // si vino con token, el paciente entró por el enlace del correo, no por WhatsApp
    canal: String($('Normalizar entrada').first().json.token || '').trim() ? 'Email' : 'WhatsApp',
    tipo: prep.actividad.tipo,
    direccion: 'Entrante',
    resumen: prep.actividad.resumen,
    intencion: prep.actividad.intencion,
    sentimiento: 'Neutro',
    generado_por: 'Bot',
    requiere_seguimiento: 'FALSE',
    url_documento: '',
  },
}];

// Lleva la salida al contrato del sub-workflow, igual que hace "Respuesta agendada".
const prep = $('Preparar gestión').first().json;
return [{
  json: {
    ...prep.respuesta,
    interpretacion: prep.respuesta.cita.texto,
    cargo_por_cancelacion_tardia: prep.cargo_por_cancelacion_tardia === true,
    alternativas: [prep.respuesta.cita],
    // Payload para "Enviar correo de la cita". En `confirmar` viene con `tipo` vacío y el
    // sub-workflow de correos corta: la confirmación vive únicamente en WhatsApp.
    correo: prep.correo || { tipo: '' },
  },
}];
